<?php
namespace App\Http\Controllers;
use App\Models\{CitaVeterinaria,ExpedienteClinico}; use App\Services\{AuditoriaService,RecetaPdfService}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class ExpedienteController extends Controller { public function store(Request $r,CitaVeterinaria $cita,RecetaPdfService $pdf,AuditoriaService $audit){abort_unless($cita->pago_confirmado,403,'La cita debe estar pagada antes de capturar el expediente.');$v=$r->validate(['diagnostico'=>'required|string|max:10000','tratamiento'=>'required|string|max:10000','constantes_ph'=>'nullable|numeric|between:0,14','constantes_temp'=>'nullable|numeric|between:-5,60']);$record=ExpedienteClinico::updateOrCreate(['cita_id'=>$cita->id],$v);$pdf->generar($record);$cita->update(['estatus'=>'Atendida']);$audit->registrar($r,'expediente.emitido:'.$record->id);return back()->with('success','Expediente y PDF generados.');} public function receta(Request $r,ExpedienteClinico $expediente,RecetaPdfService $pdf){abort_unless(in_array(mb_strtolower($r->user()->role),['veterinario','administrador'],true)||$expediente->cita->user_id===$r->user()->id,403);abort_unless($expediente->receta_pdf_path&&Storage::disk('local')->exists($expediente->receta_pdf_path),404);abort_unless($pdf->validar($expediente),409,'El hash de integridad no coincide.');return Storage::disk('local')->download($expediente->receta_pdf_path,'receta-'.$expediente->id.'.pdf');} }
